async function login(email,password,persistent=true){const r=await fetch(SUPABASE+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw new Error('Невірний логін або пароль');saveSession(d,persistent);return d}
async function refresh(){const s=getSession();if(!s?.refresh_token){const e=new Error('Сесія завершена');e.status=401;throw e}let r;try{r=await fetch(SUPABASE+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})})}catch{const e=new Error(navigator.onLine?'Не вдалося зв’язатися із сервером':'Немає інтернету');e.status=0;throw e}const d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error('Сесія завершена');e.status=r.status;e.code=d.error||'session_expired';throw e}saveSession(d,sessionPersistent());return d}
async function invokeAt(endpoint,body,retry=true){let s=getSession();if(!s?.access_token){const e=new Error('Сесія завершена');e.status=401;throw e}let r;try{r=await fetch(endpoint,{method:'POST',headers:{Authorization:`Bearer ${s.access_token}`,apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(body)})}catch{const e=new Error(navigator.onLine?'Не вдалося зв’язатися із сервером. Перевірте мережу й повторіть.':'Немає інтернету. Дані не змінено.');e.status=0;throw e}if(r.status===401&&retry){await refresh();return invokeAt(endpoint,body,false)}const d=await r.json().catch(()=>({error:'service_error'}));if(!r.ok){const labels={service_error:'Сервіс тимчасово недоступний',unauthorized:'Сесія завершена',forbidden:'Немає доступу до адмінки',inventory_conflict:'Цей слот уже зайнятий',customer_phone_exists:'Клієнт із таким номером уже існує',invalid_customer_data:'Перевірте ПІБ і номер телефону'};const e=new Error(labels[d.error]||d.error||'Помилка сервера');e.status=r.status;e.code=d.error||'service_error';throw e}return d}
const invoke=(body,retry=true)=>invokeAt(API,body,retry);
const invokeData=(body,retry=true)=>invokeAt(DATA_API,body,retry);
function toast(t,type='info'){const e=document.createElement('div');e.className=`toast ${safeToken(type)}`;e.setAttribute('role','status');e.setAttribute('aria-live','polite');e.textContent=t;document.body.append(e);requestAnimationFrame(()=>e.classList.add('show'));setTimeout(()=>{e.classList.remove('show');setTimeout(()=>e.remove(),180)},2800)}
function tval(b,k){const s=getSlots();return b?.extras?.[k]||('pickup_time'===k?(b.pickup_window==='morning'?s.morningStart:s.eveningStart):(b.return_window==='morning'?s.morningEnd:s.eveningEnd))}
function isHistoricalPhone(value){return /^history:[0-9a-f]{8,}$/i.test(String(value||''))}
function displayPhone(value){return isHistoricalPhone(value)?'—':String(value||'—')}
function isPuzzi(b){return Number(CORE.productMeta(b.product_code)?.resources?.puzzi||0)>0}
function chem(b){const c=b.extras?.chemistry||b.extras?.finance||{};return{used:Number(c.used_packets||0),story:c.story_mention===true}}
function calc(b,override={}){const historical=isHistoricalBooking(b);if(historical){const expenses=Math.max(0,Number(b.total_amount||b.base_amount||0));return{used:0,story:false,pre:0,securityDeposit:0,depositPaid:false,depositReturned:true,chemistry:0,extraItems:0,discount:0,cancelled:false,expenses,received:expenses,refund:0,due:0,historical:true}}const c=chem(b),used=override.used??c.used,story=override.story??c.story,pre=b.prepayment_paid===false?0:Number(b.prepayment_amount||200),securityDeposit=Math.max(0,Number(override.depositAmount??b.deposit_amount??depositFor(b.product_code,b.start_date,b.return_date,b.pickup_window||'morning',b.return_window||'evening'))||0),depositPaid=override.depositPaid??(b.deposit_paid===true),depositReturned=override.depositReturned??(b.deposit_returned===true),chemistry=isPuzzi(b)?Math.max(used-(story?2:0),0)*Number(getCatalog().puzziPacketPrice||50):0,discount=Number(b.extras?.discount?.percent||0),extraItems=extrasTotal(b),cancelled=['cancelled','declined'].includes(b.status),expenses=cancelled?0:Number(b.base_amount||0)+Number(b.delivery_amount||0)+extraItems+chemistry,received=pre+(depositPaid?securityDeposit:0),balance=received-expenses;return{used,story,pre,securityDeposit,depositPaid,depositReturned,chemistry,extraItems,discount,cancelled,expenses,received,refund:cancelled?received:Math.max(balance,0),due:cancelled?0:Math.max(-balance,0)}}
function pimgs(b){return CORE.productImages(b.product_code)}
function recalcCalendarSlots(days,bookings){const active=(bookings||[]).filter(b=>b.status==='confirmed'||b.status==='issued'||(b.status==='waiting_payment'&&b.hold_expires_at&&new Date(b.hold_expires_at).getTime()>Date.now()));const dayNumber=date=>Math.floor(new Date(`${date}T12:00:00Z`).getTime()/86400000),slotIndex=(date,window)=>dayNumber(date)*2+(window==='evening'?1:0),bookingWindow=(b,kind)=>kind==='start'?(b.pickup_window||slotForTime(tval(b,'pickup_time'))):(b.return_window||slotForTime(tval(b,'return_time'))),bookingIndex=(b,kind)=>slotIndex(kind==='start'?b.start_date:b.return_date,bookingWindow(b,kind));return(days||[]).map(day=>{const resources={};for(const [code,row] of Object.entries(day.resources||{})){const capacity=Number(row.capacity||0),countAt=window=>active.reduce((sum,b)=>{const at=slotIndex(day.date,window),start=bookingIndex(b,'start'),end=bookingIndex(b,'end');if(!(start<=at&&at<end))return sum;const resource=(b.vacleaner_booking_resources||[]).find(r=>r.resource_code===code);return sum+Number(resource?.quantity||0)},0);resources[code]={...row,morning:Math.max(0,capacity-countAt('morning')),evening:Math.max(0,capacity-countAt('evening'))}}return{...day,resources}})}
async function load(){const [b,c,clients]=await Promise.all([invokeData({action:'list'}),invoke({action:'calendar',from:todayIso(),days:14}),invokeData({action:'clients'})]);state.bookings=b.bookings||[];state.calendar=recalcCalendarSlots(c.days||[],state.bookings);state.customers=clients.customers||[];renderBadges()}
