function renderAnalytics(){
const period=state.analyticsPeriod||'30',now=new Date(),startOfMonth=new Date(now.getFullYear(),now.getMonth(),1),cutoff=period==='7'?new Date(now.getTime()-7*86400000):period==='30'?new Date(now.getTime()-30*86400000):period==='month'?startOfMonth:null;
const inPeriod=b=>!cutoff||new Date(b.completed_at||b.updated_at||b.created_at||b.start_at)>=cutoff;
const created=state.bookings.filter(b=>!cutoff||new Date(b.created_at||b.start_at)>=cutoff),completed=state.bookings.filter(b=>b.status==='completed'&&inPeriod(b)),confirmedFuture=state.bookings.filter(b=>['confirmed','issued'].includes(b.status)&&new Date(b.start_at)>=now),cancelled=created.filter(b=>['cancelled','declined'].includes(b.status));
const rev=completed.reduce((sum,b)=>sum+Number(b.total_amount||0),0),delivery=completed.reduce((sum,b)=>sum+Number(b.delivery_amount||0),0),chemistry=completed.reduce((sum,b)=>sum+calc(b).chemistry,0),extraRevenue=completed.reduce((sum,b)=>sum+extrasTotal(b),0),avg=completed.length?Math.round(rev/completed.length):0,conversion=created.length?Math.round(completed.length/created.length*100):0,by={},extraBy={};
completed.forEach(b=>{const key=b.product_label||products[b.product_code]||b.product_code;const row=by[key]||(by[key]={count:0,revenue:0});row.count+=1;row.revenue+=Number(b.total_amount||0);getSelectedExtras(b).forEach(item=>{const x=extraBy[item.label]||(extraBy[item.label]={count:0,revenue:0});x.count+=1;x.revenue+=Number(item.price||0)})});
const arr=Object.entries(by).sort((a,b)=>b[1].count-a[1].count||b[1].revenue-a[1].revenue),extrasArr=Object.entries(extraBy).sort((a,b)=>b[1].revenue-a[1].revenue),max=Math.max(1,...arr.map(x=>x[1].count)),statusCounts=Object.fromEntries(Object.keys(statusText).map(k=>[k,state.bookings.filter(b=>b.status===k).length])),statusMax=Math.max(1,...Object.values(statusCounts));
const periods=[['7','7 днів'],['30','30 днів'],['month','Цей місяць'],['all','Увесь час']];
$('#view').innerHTML=`<div class="analytics-toolbar"><div><h2>Показники</h2><p>За вибраний період. Виручка рахується лише із завершених оренд.</p></div><div class="analytics-periods">${periods.map(([k,l])=>`<button class="chip ${period===k?'active':''}" data-analytics-period="${k}">${l}</button>`).join('')}</div></div><div class="kpi-grid">${[['Створено заявок',created.length],['Завершено оренд',completed.length],['Майбутні підтверджені',confirmedFuture.length],['Скасовано',cancelled.length],['Виручка',money(rev)],['Середній чек',money(avg)],['Конверсія у завершення',conversion+'%'],['Додатково',money(extraRevenue+chemistry+delivery)]].map(x=>`<article class="card kpi"><span>${x[0]}</span><strong>${x[1]}</strong></article>`).join('')}</div><div class="analytics-grid"><article class="card analytics-panel"><h3>Популярність техніки</h3>${arr.map(([n,v])=>`<div class="bar-row"><div class="product-analytics-row"><span>${n}</span><span class="product-stats"><b>${v.count} ор.</b><strong>${money(v.revenue)}</strong></span></div><div class="bar"><i style="width:${v.count/max*100}%"></i></div></div>`).join('')||'<p>За цей період завершених оренд ще немає.</p>'}</article><article class="card analytics-panel"><h3>Додаткові позиції</h3>${extrasArr.map(([n,v])=>`<div class="analytics-line"><span>${n}<small>${v.count} зам.</small></span><strong>${money(v.revenue)}</strong></div>`).join('')||'<p>За цей період продажів ще немає.</p>'}</article><article class="card analytics-panel analytics-status-panel"><div class="status-panel-head"><div><h3>Статуси бронювань</h3><p>Поточний стан усієї бази, незалежно від фільтра періоду</p></div><strong>${state.bookings.length}</strong></div><div class="status-dashboard">${Object.entries(statusText).map(([k,l])=>`<div class="analytics-status-item status-${k}"><div class="status-row-top"><span><i></i>${l}</span><strong>${statusCounts[k]}</strong></div><div class="status-progress"><b style="width:${statusCounts[k]/statusMax*100}%"></b></div></div>`).join('')}</div></article></div>`;
$$('[data-analytics-period]').forEach(btn=>btn.onclick=()=>{state.analyticsPeriod=btn.dataset.analyticsPeriod;renderAnalytics()})}


