const auditFieldLabels={status:'Статус',prepayment_paid:'Передплата',prepayment_amount:'Сума передплати',issue_payment_amount:'Застаріле поле оплати',issue_payment_paid:'Застаріле підтвердження оплати',return_payment_amount:'Оплата при поверненні',return_payment_paid:'Оплату при поверненні підтверджено',deposit_amount:'Залоговий платіж',deposit_paid:'Залоговий платіж отримано',deposit_returned:'Фінальний розрахунок завершено',base_amount:'Оренда',extras_amount:'Додатково',delivery_amount:'Доставка',total_amount:'Разом',extras:'Склад і хімія'};
function auditValue(field,value){if(field==='status')return statusText[value]||value||'—';if(['prepayment_paid','issue_payment_paid','return_payment_paid','deposit_paid','deposit_returned'].includes(field))return value?'Так':'Ні';if(field==='extras')return 'оновлено';if(field.endsWith('_amount'))return money(value);return value==null||value===''?'—':String(value)}
function auditEventTitle(entry){if(entry.event_type==='created')return 'Бронювання створено';const fields=entry.changed_fields||[];if(fields.includes('status'))return `Статус: ${auditValue('status',entry.new_values?.status)}`;if(fields.some(x=>x.includes('deposit')))return 'Оновлено залог';if(fields.some(x=>x.includes('payment')||x.endsWith('_amount')))return 'Оновлено фінанси';return 'Дані бронювання оновлено'}
function renderAuditEntries(entries){if(!entries?.length)return '<div class="audit-empty">Історія змін ще порожня.</div>';return entries.map(entry=>{const fields=(entry.changed_fields||[]).filter(x=>auditFieldLabels[x]);const changes=fields.slice(0,6).map(field=>`<div><span>${h(auditFieldLabels[field])}</span><strong>${h(auditValue(field,entry.old_values?.[field]))} → ${h(auditValue(field,entry.new_values?.[field]))}</strong></div>`).join('');return `<article class="audit-entry"><div class="audit-entry-dot"></div><div class="audit-entry-body"><header><strong>${h(auditEventTitle(entry))}</strong><time>${new Intl.DateTimeFormat('uk-UA',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(entry.created_at))}</time></header>${changes?`<div class="audit-entry-changes">${changes}</div>`:''}<small>${entry.source==='backfill'?'Початковий стан':entry.actor_id?'Дія менеджера':'Зафіксовано системою'}</small></div></article>`}).join('')}
async function loadAuditLog(bookingId){const box=$('#auditContent');if(!box)return;box.innerHTML='<div class="audit-loading">Завантажуємо історію…</div>';try{const data=await invoke({action:'audit_log',bookingId,limit:60});setMarkup(box,renderAuditEntries(data.entries||[]))}catch(error){box.innerHTML='<div class="audit-empty">Не вдалося завантажити історію.</div>'}}

function openDetail(b){detailRestoreVersion+=1;state.listScroll=$('.main')?.scrollTop||0;state.detail=b;document.body.classList.add('detail-open');document.documentElement.classList.add('detail-open');const f=calc(b),idx={pending:0,waiting_payment:0,confirmed:1,issued:2,completed:3}[b.status]??0,phone=normalizePhone(b.customer_phone);setMarkup($('#layer'),`<div class="detail"><div class="detail-shell"><div class="detail-top"><button class="back">← До бронювань</button><div class="detail-top-meta"><span>${h(b.booking_code)}</span><small>Створено ${date(b.created_at)}</small></div></div><section class="detail-hero"><div class="detail-hero-copy"><div class="detail-title-row"><h1>${h(b.product_label)}</h1><span class="hero-status">✓ ${h(statusText[b.status]||b.status)}</span></div><div class="period"><b>${date(b.start_date)}</b> · ${h(tval(b,'pickup_time'))} → <b>${date(b.return_date)}</b> · ${h(tval(b,'return_time'))}<small>${Number(b.rental_days||1)} доба</small></div></div><div class="hero-images">${pimgs(b).map(i=>`<img src="${h(i)}" alt="">`).join('')}</div></section><article class="card flow flow-compact"><div><h3>Хід бронювання</h3><p>Поточний етап: <b>${h(statusText[b.status]||b.status)}</b></p></div><div class="steps">${['Нове','Підтверджено','Видано','Повернено'].map((x,i)=>`<div class="step ${i<=idx?'done':''}"><i>${i<=idx?'✓':i+1}</i><b>${x}</b></div>`).join('')}</div></article><div class="detail-grid"><div class="detail-left"><div class="info-grid"><article class="card panel"><h3>Клієнт</h3><h2>${h(b.customer_name)}</h2><p><a href="tel:${h(phone)}">${h(b.customer_phone)}</a></p><p>${h(b.customer_telegram||'Telegram не вказаний')}</p></article><article class="card panel"><h3>Видача</h3><h2>${b.fulfillment==='delivery'?'Доставка':'Самовивіз'}</h2><p>${b.fulfillment==='delivery'?money(b.delivery_amount):'Безкоштовно'}</p><p>${h(b.fulfillment_address||'вул. Європейська, 146Е')}</p></article>${getSelectedExtras(b).length?`<article class="card panel extras-panel"><h3>Додатково</h3>${getSelectedExtras(b).map(x=>`<div><span>${h(x.label)}</span><strong>${extraPriceHtml(b,x)}</strong></div>`).join('')}</article>`:''}<article class="card panel comment"><h3>Коментар</h3><p>${h(b.customer_comment||b.admin_note||'Коментаря немає')}</p></article></div></div><article class="card panel finance-panel"><h3>Фінанси</h3>${moneyRows(b,f)}</article></div><article class="card audit-panel"><div class="audit-panel-head"><div><small>Контроль змін</small><h3>Історія бронювання</h3></div><button class="btn" type="button" id="auditReload">Оновити</button></div><div id="auditContent" class="audit-list"><div class="audit-loading">Завантажуємо історію…</div></div></article><div class="detail-actions actions">${actions(b)}</div></div></div>`);$('.back').onclick=closeDetail;$$('[data-action]',$('.detail-actions')).forEach(btn=>btn.onclick=()=>handleAction(b,btn.dataset.action));$('#auditReload').onclick=()=>loadAuditLog(b.id);loadAuditLog(b.id)}
function moneyRows(b,f){const depositLabel=f.depositReturned?'Взаєморозрахунок завершено':f.depositPaid?'Фактично отримано при видачі':'Очікується при видачі';if(f.cancelled)return`<div class="cancel-finance-note">Скасоване бронювання: оренда, доставка та хімія не нараховуються.</div><div class="money-row"><span>Передоплата за бронювання</span><strong>${money(f.pre)}</strong></div><div class="money-row"><span>Фактичний залоговий платіж <small>${depositLabel}</small></span><strong>${money(f.depositPaid?f.securityDeposit:0)}</strong></div><div class="money-row"><span>Отримано разом</span><strong>${money(f.received)}</strong></div><div class="balance refund"><span>Повернути клієнту</span><strong>${money(f.refund)}</strong></div>`;return`<div class="money-row"><span>Передоплата за бронювання <small>входить у фінальний взаєморозрахунок</small></span><strong>${money(f.pre)}</strong></div><div class="money-row"><span>Фактичний залоговий платіж <small>${depositLabel}</small></span><strong>${money(f.depositPaid?f.securityDeposit:0)}</strong></div><div class="money-row received-total"><span>Отримано разом</span><strong>${money(f.received)}</strong></div><div class="money-row"><span>Оренда</span><strong>${money(b.base_amount)}</strong></div><div class="money-row"><span>Доставка</span><strong>${money(b.delivery_amount)}</strong></div>${f.extraItems?`<div class="money-row"><span>Додатково <small>${getSelectedExtras(b).map(x=>x.label).join(', ')}</small></span><strong>${money(f.extraItems)}</strong></div>`:''}${isPuzzi(b)?`<div class="money-row"><span>Хімія <small>${f.used} використано${f.story?' · 2 бонусні':''}</small></span><strong>${money(f.chemistry)}</strong></div>`:''}<div class="money-row expenses-total"><span>Разом витрати</span><strong>${money(f.expenses)}</strong></div><div class="balance ${f.refund?'refund':f.due?'due':'neutral'}"><span>${f.refund?'Повернути клієнту':f.due?'Клієнт має доплатити':'Фінальний баланс 0 грн'}</span><strong>${money(f.refund||f.due)}</strong></div>`}
function closeDetail(){const restoreTop=Math.max(0,Number(state.listScroll)||0);detailRestoreVersion+=1;state.detail=null;document.activeElement instanceof HTMLElement&&document.activeElement.blur();document.body.classList.remove('detail-open');document.documentElement.classList.remove('detail-open');$('#layer').innerHTML='';const main=$('.main');if(main){void main.offsetHeight;main.scrollTop=restoreTop}window.scrollTo(0,0)}
function modal(html){modalReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;document.body.classList.add('modal-open');document.documentElement.classList.add('modal-open');setMarkup($('#layer'),`<div class="modal"><button class="modal-backdrop" aria-label="Закрити"></button><div class="modal-card" role="dialog" aria-modal="true">${html}</div></div>`);$('.modal-backdrop').onclick=closeLayer;$$('[data-close]').forEach(x=>x.onclick=closeLayer);const card=$('.modal-card'),focusable=()=>[...card.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetParent!==null);modalKeyHandler=e=>{if(e.key!=='Tab')return;const list=focusable();if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',modalKeyHandler);const resetModalScroll=()=>{card.querySelectorAll('.booking-form-scroll,.process-grid,.catalog-scroll,.client-editor-scroll,.issue-form .modal-layout,.finance-form .modal-layout').forEach(el=>{el.scrollTop=0;el.scrollLeft=0})};resetModalScroll();requestAnimationFrame(()=>{resetModalScroll();const first=focusable()[0];if(first){try{first.focus({preventScroll:true})}catch{first.focus()}}requestAnimationFrame(resetModalScroll)})}
