function live(b,o){const f=calc(b,o),depositLabel=f.depositReturned?'Розрахунок завершено':f.depositPaid?'Отримано':'Очікується';return`<div class="live"><div><span>Передоплата за бронювання</span><strong>${money(f.pre)}</strong></div><div><span>Фактичний залоговий платіж <small>${depositLabel}</small></span><strong>${money(f.depositPaid?f.securityDeposit:0)}</strong></div><div class="received-total"><span>Отримано разом</span><strong>${money(f.received)}</strong></div><div><span>Оренда</span><strong>${money(b.base_amount)}</strong></div><div><span>Доставка</span><strong>${money(b.delivery_amount)}</strong></div>${f.extraItems?`<div><span>Додатково</span><strong>${money(f.extraItems)}</strong></div>`:''}${isPuzzi(b)?`<div><span>Хімія</span><strong>${f.used} − ${f.story?2:0} бонус = ${money(f.chemistry)}</strong></div>`:''}<div class="expenses-total"><span>Разом витрати</span><strong>${money(f.expenses)}</strong></div><div class="balance ${f.refund?'refund':f.due?'due':'neutral'}"><span>${f.refund?'Повернути клієнту':f.due?'Клієнт має доплатити':'Фінальний баланс 0 грн'}</span><strong>${money(f.refund||f.due)}</strong></div></div>`}

function confirmationMessage(b,form){const fd=new FormData(form),pickup=b.fulfillment==='delivery'?`Доставка: ${b.fulfillment_address||'адреса уточнюється'}`:'Самовивіз: Полтава, вул. Європейська, 146Е',documentsRequired=form.dataset.documentsRequired==='1',docText=documentsRequired?'Надішліть фото паспорта, ID-картки або водійського посвідчення у цьому чаті. Дані потрібні лише для заповнення договору оренди.':'Документи повторно надсилати не потрібно — клієнт уже орендував техніку, дані є в базі.',deposit=Number(b.deposit_amount||depositFor(b.product_code,b.start_date,b.return_date,b.pickup_window||'morning',b.return_window||'evening'));return `Вітаю! Бронювання ${b.product_label} підтверджено ✅\n\nВидача: ${fullDate(b.start_date)}, ${tval(b,'pickup_time')}\nПовернення: ${fullDate(b.return_date)}, ${tval(b,'return_time')}\n${pickup}\n\nУмови оренди ✨\n\n1. Передплата — 200 грн. Вона закріплює дату та входить у фінальний взаєморозрахунок.\n\nФОП Невідома Анна Сергіївна\nIBAN: UA523220010000026006370119233\nІПН: 3314215243\nПризначення: сплата за оренду техніки\n\n2. ${docText}\n\n3. Залоговий платіж — ${money(deposit)}. Він сплачується під час отримання техніки. Після повернення техніки із передоплати та фактично отриманого залогу вираховується вартість оренди, доставки, додаткових засобів і використаної хімії. Залишок повертається клієнту або клієнт доплачує різницю.\n\nПеред видачею менеджер ще раз підтвердить час. Якщо є питання — напишіть у відповідь на це повідомлення.`}
